export const emptyData=()=>({format:'attention-backup',version:2,tasks:[],roadmaps:[],sessions:[],preferences:{onboarded:true}});
export function validateBackup(d){if(!d||d.format!=='attention-backup'||![1,2].includes(d.version)||!Array.isArray(d.tasks)||!Array.isArray(d.sessions)||!d.preferences||typeof d.preferences!=='object')throw Error('Выберите резервную копию Attention.');d.roadmaps??=[];if(!Array.isArray(d.roadmaps)||d.tasks.length>50000||d.roadmaps.length>200)throw Error('Слишком много записей.');const ids=new Set();for(const t of d.tasks){if(typeof t.id!=='string'||ids.has(t.id)||typeof t.title!=='string'||!t.title.trim()||t.title.length>120||!Number.isFinite(t.start)||!Number.isInteger(t.minutes)||t.minutes<1||t.minutes>720)throw Error('Некорректная задача в копии.');ids.add(t.id)}for(const m of d.roadmaps){if(typeof m.id!=='string'||typeof m.title!=='string'||!m.title.trim()||m.title.length>120||!Array.isArray(m.steps)||m.steps.length>1000)throw Error('Некорректная роадмапа.');const steps=new Set();for(const s of m.steps){if(typeof s.id!=='string'||steps.has(s.id)||typeof s.title!=='string'||!s.title.trim()||s.title.length>240||typeof s.done!=='boolean'||(s.date!=null&&(!Number.isFinite(s.date)||new Date(s.date).getFullYear()<2000||new Date(s.date).getFullYear()>2100)))throw Error('Некорректный шаг.');steps.add(s.id)}}return {...d,version:2}}
export function parseMarkdown(text,name='Мой путь'){if(text.length>2*1024*1024||text.includes('\0'))throw Error('Выберите Markdown до 2 МБ.');let lines=text.replace(/^\uFEFF/,'').split(/\r?\n/),code=false,section='',title=name.replace(/\.(md|txt|markdown)$/i,''),description='';if(lines[0]?.trim()==='---'){const end=lines.findIndex((l,i)=>i>0&&l.trim()==='---');if(end>0)lines=lines.slice(end+1)}lines=lines.filter(l=>{if(/^\s*(```|~~~)/.test(l)){code=!code;return false}return !code});const checks=lines.some(l=>/^\s*[-*+] \[[ xX]\] /.test(l)),steps=[];for(const l of lines){const h=l.match(/^(#{1,6})\s+(.+)/);if(h){if(h[1]==='#'&&!steps.length)title=h[2];else section=h[2];continue}const m=l.match(checks?/^(\s*)[-*+] \[([ xX])\]\s+(.+)/:/^(\s*)(?:[-*+]|\d+[.)])\s+(.+)/);if(m){let raw=checks?m[3]:m[2],date=null;const due=raw.match(/(?:📅\s*|\[?due::?\s*)(\d{4}-\d{2}-\d{2})\]?/);if(due){const parsed=new Date(due[1]+'T12:00:00');if(!Number.isFinite(+parsed)||[parsed.getFullYear(),String(parsed.getMonth()+1).padStart(2,'0'),String(parsed.getDate()).padStart(2,'0')].join('-')!==due[1])throw Error('Некорректная дата.');date=+new Date(due[1]+'T00:00:00');raw=raw.replace(due[0],'')}steps.push({id:crypto.randomUUID(),title:raw.replace(/\[\[([^\]]+)\]\]/g,(_,s)=>s.split('|').pop()).trim(),section,note:'',comment:'',done:checks&&m[2].toLowerCase()==='x',date,level:Math.min(12,Math.floor(m[1].length/2))})}else if(l.trim()){if(steps.length&&steps.at(-1).section===section)steps.at(-1).note+=l.trim()+'\n';else description+=l.trim()+'\n'}}if(!steps.length||steps.length>1000)throw Error('Добавьте список шагов: - [ ] Тема. Максимум 1000 шагов.');const r={id:crypto.randomUUID(),title,description:description.trim(),source:name,steps};validateBackup({...emptyData(),roadmaps:[r]});return r}
